def string_to_md5(text):
    """
    This function takes a string 'text' and computes its MD5 hash, returning the result as a hexadecimal string.
    In case the input string is empty, the function will return None.

    >>> string_to_md5('Hello world') == '3e25960a79dbc69b674cd4ec67a72c62'
